const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Isabela Island geometry (Galápagos, Ecuador)
  // Northern part: roughly above -0.65° latitude
  const northIsabela = ee.Geometry.Polygon([
    [[-91.2, -0.25], [-90.8, -0.25], [-90.8, -0.65], [-91.2, -0.65], [-91.2, -0.25]]
  ]);

  // Southern part: roughly below -0.65° latitude
  const southIsabela = ee.Geometry.Polygon([
    [[-91.2, -0.65], [-90.8, -0.65], [-90.8, -1.08], [-91.2, -1.08], [-91.2, -0.65]]
  ]);

  // Date: January 7, 2022
  const targetDate = '2022-01-07';

  // Load VIIRS DNB nighttime lights daily product
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2022-01-01', '2022-01-31')
    .select('avg_rad');

  const colSize = collection.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No VIIRS data available for January 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the image (monthly composite for January 2022)
  const image = collection.first();

  // Calculate mean brightness for northern part
  const northStats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northIsabela,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const northBrightness = northStats['avg_rad_mean'];
  const northCount = northStats['avg_rad_count'];

  console.log(`North Isabela - Brightness: ${northBrightness}, Pixels: ${northCount}`);

  // Calculate mean brightness for southern part
  const southStats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southIsabela,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const southBrightness = southStats['avg_rad_mean'];
  const southCount = southStats['avg_rad_count'];

  console.log(`South Isabela - Brightness: ${southBrightness}, Pixels: ${southCount}`);

  // Check for no valid pixels
  if (northCount === 0 || southCount === 0) {
    console.log('No valid pixels in one or both regions.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for null/invalid values
  if (northBrightness === null || southBrightness === null || 
      isNaN(northBrightness) || isNaN(southBrightness)) {
    console.log('Invalid brightness values calculated.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare brightness
  console.log(`Comparison: North (${northBrightness.toFixed(4)}) vs South (${southBrightness.toFixed(4)})`);

  if (northBrightness > southBrightness) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
